    10→// Upload represents a file upload record for tracking purposes.
    11→type Upload struct {
    12→	ID            int64  `json:"id"`
    13→	Filename      string `json:"filename"`
    14→	FileType      string `json:"fileType"`
    15→	TrackID       string `json:"trackID"`
    16→	FileSize      int64  `json:"fileSize"`
    17→	UploadIP      string `json:"uploadIP"`
    18→	CreatedAt     int64  `json:"createdAt"`
    19→	RecordingDate int64  `json:"recordingDate,omitempty"` // Earliest marker date for this track
    20→	Source        string `json:"source,omitempty"`        // Import source (e.g., "safecast-api", "user-upload")
    21→	SourceID      string `json:"sourceID,omitempty"`      // External reference ID (e.g., Safecast import ID)
    22→	SourceURL     string `json:"sourceURL,omitempty"`     // Source file URL (e.g., S3 URL)
    23→	UserID         string `json:"userID,omitempty"`         // User ID from source (e.g., Safecast user ID)
    24→	Username       string `json:"username,omitempty"`       // Username from source (fetched from API)
    25→	InternalUserID string `json:"internalUserID,omitempty"` // Internal user ID from users table (for authenticated uploads)
    26→	Detector       string `json:"detector,omitempty"`       // Detector info from track_statistics
    27→}
    28→
    29→// InsertUpload records a file upload in the uploads table.
    30→func (db *Database) InsertUpload(ctx context.Context, upload Upload) (int64, error) {
    31→	createdAt := upload.CreatedAt
    32→	if createdAt == 0 {
    33→		createdAt = time.Now().Unix()
    34→	}
    35→
    36→	var query string
    37→	var args []interface{}
    38→	var id int64
    39→
    40→	switch db.Driver {
    41→	case "pgx":
    42→		query = `
    43→			INSERT INTO uploads (filename, file_type, track_id, file_size, upload_ip, created_at, recording_date, source, source_id, source_url, user_id, username, internal_user_id, detector)
    44→			VALUES ($1, $2, $3, $4, $5, to_timestamp($6), to_timestamp($7), $8, $9, $10, $11, $12, $13, $14)
    45→			RETURNING id
    46→		`
    47→		recordingDateArg := upload.RecordingDate
    48→		if recordingDateArg == 0 {
    49→			recordingDateArg = createdAt
    50→		}
    51→		args = []interface{}{
    52→			upload.Filename, upload.FileType, upload.TrackID,
    53→			upload.FileSize, upload.UploadIP, createdAt, recordingDateArg,
    54→			upload.Source, upload.SourceID, upload.SourceURL, upload.UserID, upload.Username, upload.InternalUserID, upload.Detector,
    55→		}
    56→		err := db.DB.QueryRowContext(ctx, query, args...).Scan(&id)
    57→		return id, err
    58→
    59→	case "duckdb":
    60→		query = `
    61→			INSERT INTO uploads (filename, file_type, track_id, file_size, upload_ip, created_at, recording_date, source, source_id, source_url, user_id, username, internal_user_id, detector)
    62→			VALUES ($1, $2, $3, $4, $5, to_timestamp($6), to_timestamp($7), $8, $9, $10, $11, $12, $13, $14)
    63→			RETURNING id
    64→		`
    65→		recordingDateArg := upload.RecordingDate
    66→		if recordingDateArg == 0 {
    67→			recordingDateArg = createdAt
    68→		}
    69→		args = []interface{}{
    70→			upload.Filename, upload.FileType, upload.TrackID,
    71→			upload.FileSize, upload.UploadIP, createdAt, recordingDateArg,
    72→			upload.Source, upload.SourceID, upload.SourceURL, upload.UserID, upload.Username, upload.InternalUserID, upload.Detector,
    73→		}
    74→		err := db.DB.QueryRowContext(ctx, query, args...).Scan(&id)
    75→		return id, err
    76→
    77→	case "sqlite", "chai":
    78→		query = `
    79→			INSERT INTO uploads (filename, file_type, track_id, file_size, upload_ip, created_at, recording_date, source, source_id, source_url, user_id, username, internal_user_id, detector)
    80→			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    81→		`
    82→		recordingDateArg := upload.RecordingDate
    83→		if recordingDateArg == 0 {
    84→			recordingDateArg = createdAt
    85→		}
    86→		args = []interface{}{
    87→			upload.Filename, upload.FileType, upload.TrackID,
    88→			upload.FileSize, upload.UploadIP, createdAt, recordingDateArg,
    89→			upload.Source, upload.SourceID, upload.SourceURL, upload.UserID, upload.Username, upload.InternalUserID, upload.Detector,
    90→		}
    91→		result, err := db.DB.ExecContext(ctx, query, args...)
    92→		if err != nil {
    93→			return 0, err
    94→		}
    95→		return result.LastInsertId()
    96→
    97→	default:
    98→		return 0, fmt.Errorf("unsupported database driver: %s", db.Driver)
    99→	}
   100→}
