   260→// DeleteTrack removes all data associated with a track ID.
   261→// This includes markers, spectra, and upload records.
   262→func (db *Database) DeleteTrack(ctx context.Context, trackID string) error {
   263→	// Delete from spectra first (via CASCADE from markers)
   264→	// Then delete markers, tracks, and upload records
   265→
   266→	queries := []string{
   267→		"DELETE FROM markers WHERE trackID = ?",
   268→		"DELETE FROM tracks WHERE trackID = ?",
   269→		"DELETE FROM uploads WHERE track_id = ?",
   270→	}
   271→
   272→	if db.Driver == "pgx" || db.Driver == "duckdb" {
   273→		queries = []string{
   274→			"DELETE FROM markers WHERE trackID = $1",
   275→			"DELETE FROM tracks WHERE trackID = $1",
   276→			"DELETE FROM uploads WHERE track_id = $1",
   277→		}
   278→	}
   279→
   280→	for _, query := range queries {
   281→		_, err := db.DB.ExecContext(ctx, query, trackID)
   282→		if err != nil {
   283→			return fmt.Errorf("delete track data: %w", err)
   284→		}
   285→	}
   286→
   287→	return nil
   288→}
