   290→// CheckImportExists returns true if a Safecast import ID has already been imported AND has data points.
   291→func (db *Database) CheckImportExists(ctx context.Context, sourceType string, importID int64) (bool, error) {
   292→	var query string
   293→	var args []interface{}
   294→
   295→	sourceIDStr := fmt.Sprintf("%d", importID)
   296→
   297→	switch db.Driver {
   298→	case "pgx", "duckdb":
   299→		// Check if upload exists AND has markers (actual data points)
   300→		query = `SELECT COUNT(*) FROM uploads u
   301→		         WHERE u.source = $1 AND u.source_id = $2
   302→		         AND EXISTS (SELECT 1 FROM markers m WHERE m.trackid = u.track_id LIMIT 1)`
   303→		args = []interface{}{sourceType, sourceIDStr}
   304→	case "sqlite", "chai":
   305→		// Check if upload exists AND has markers (actual data points)
   306→		query = `SELECT COUNT(*) FROM uploads u
   307→		         WHERE u.source = ? AND u.source_id = ?
   308→		         AND EXISTS (SELECT 1 FROM markers m WHERE m.trackid = u.track_id LIMIT 1)`
   309→		args = []interface{}{sourceType, sourceIDStr}
   310→	default:
   311→		return false, fmt.Errorf("unsupported database driver: %s", db.Driver)
   312→	}
   313→
   314→	var count int
   315→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&count)
   316→	if err != nil {
   317→		return false, fmt.Errorf("check import exists: %w", err)
   318→	}
   319→
   320→	return count > 0, nil
   321→}
