   323→// GetLastImportedSafecastID returns the highest Safecast import ID that has been processed.
   324→func (db *Database) GetLastImportedSafecastID(ctx context.Context, sourceType string) (int64, error) {
   325→	var query string
   326→	var args []interface{}
   327→
   328→	switch db.Driver {
   329→	case "pgx", "duckdb":
   330→		// PostgreSQL and DuckDB: CAST to INTEGER
   331→		query = `
   332→			SELECT COALESCE(MAX(CAST(source_id AS INTEGER)), 0)
   333→			FROM uploads
   334→			WHERE source = $1 AND source_id IS NOT NULL AND source_id != ''
   335→		`
   336→		args = []interface{}{sourceType}
   337→	case "sqlite", "chai":
   338→		// SQLite: CAST to INTEGER
   339→		query = `
   340→			SELECT COALESCE(MAX(CAST(source_id AS INTEGER)), 0)
   341→			FROM uploads
   342→			WHERE source = ? AND source_id IS NOT NULL AND source_id != ''
   343→		`
   344→		args = []interface{}{sourceType}
   345→	default:
   346→		return 0, fmt.Errorf("unsupported database driver: %s", db.Driver)
   347→	}
   348→
   349→	var lastID int64
   350→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&lastID)
   351→	if err != nil {
   352→		return 0, fmt.Errorf("get last imported safecast ID: %w", err)
   353→	}
   354→
   355→	return lastID, nil
   356→}
   357→
   358→// GetMinImportedSafecastID returns the lowest Safecast import ID that has been processed.
   359→// This is used for backfill to know where to continue from.
   360→func (db *Database) GetMinImportedSafecastID(ctx context.Context, sourceType string) (int64, error) {
   361→	var query string
   362→	var args []interface{}
   363→
   364→	switch db.Driver {
   365→	case "pgx", "duckdb":
   366→		query = `
   367→			SELECT COALESCE(MIN(CAST(source_id AS INTEGER)), 0)
   368→			FROM uploads
   369→			WHERE source = $1 AND source_id IS NOT NULL AND source_id != ''
   370→		`
   371→		args = []interface{}{sourceType}
   372→	case "sqlite", "chai":
   373→		query = `
   374→			SELECT COALESCE(MIN(CAST(source_id AS INTEGER)), 0)
   375→			FROM uploads
   376→			WHERE source = ? AND source_id IS NOT NULL AND source_id != ''
   377→		`
   378→		args = []interface{}{sourceType}
   379→	default:
   380→		return 0, fmt.Errorf("unsupported database driver: %s", db.Driver)
   381→	}
   382→
   383→	var minID int64
   384→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&minID)
   385→	if err != nil {
   386→		return 0, fmt.Errorf("get min imported safecast ID: %w", err)
   387→	}
   388→
   389→	return minID, nil
   390→}
