   392→// CountImportsBySource returns the number of uploads from a specific source.
   393→func (db *Database) CountImportsBySource(ctx context.Context, sourceType string) (int, error) {
   394→	var query string
   395→	var args []interface{}
   396→
   397→	switch db.Driver {
   398→	case "pgx", "duckdb":
   399→		query = `SELECT COUNT(*) FROM uploads WHERE source = $1`
   400→		args = []interface{}{sourceType}
   401→	case "sqlite", "chai":
   402→		query = `SELECT COUNT(*) FROM uploads WHERE source = ?`
   403→		args = []interface{}{sourceType}
   404→	default:
   405→		return 0, fmt.Errorf("unsupported database driver: %s", db.Driver)
   406→	}
   407→
   408→	var count int
   409→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&count)
   410→	if err != nil {
   411→		return 0, fmt.Errorf("count imports by source: %w", err)
   412→	}
   413→
   414→	return count, nil
   415→}
