   417→// GetLatestImportDate returns the latest created_at date for imports from a specific source.
   418→// Returns empty string if no imports exist.
   419→func (db *Database) GetLatestImportDate(ctx context.Context, sourceType string) (string, error) {
   420→	var query string
   421→	var args []interface{}
   422→
   423→	switch db.Driver {
   424→	case "pgx":
   425→		query = `SELECT TO_CHAR(MAX(created_at), 'YYYY-MM-DD') FROM uploads WHERE source = $1`
   426→		args = []interface{}{sourceType}
   427→	case "duckdb":
   428→		query = `SELECT strftime(MAX(created_at), '%Y-%m-%d') FROM uploads WHERE source = $1`
   429→		args = []interface{}{sourceType}
   430→	case "sqlite", "chai":
   431→		query = `SELECT strftime('%Y-%m-%d', MAX(created_at), 'unixepoch') FROM uploads WHERE source = ?`
   432→		args = []interface{}{sourceType}
   433→	default:
   434→		return "", fmt.Errorf("unsupported database driver: %s", db.Driver)
   435→	}
   436→
   437→	var dateStr sql.NullString
   438→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&dateStr)
   439→	if err != nil {
   440→		return "", fmt.Errorf("get latest import date: %w", err)
   441→	}
   442→
   443→	if !dateStr.Valid {
   444→		return "", nil
   445→	}
   446→
   447→	return dateStr.String, nil
   448→}
