   450→// CountUploads returns the total number of uploads, optionally filtered by user_id and search term
   451→func (db *Database) CountUploads(ctx context.Context, userID string, search string) (int, error) {
   452→	var query string
   453→	var args []interface{}
   454→	var whereConditions []string
   455→	paramCount := 0
   456→
   457→	// Build WHERE conditions
   458→	if userID != "" {
   459→		paramCount++
   460→		if db.Driver == "pgx" || db.Driver == "duckdb" {
   461→			whereConditions = append(whereConditions, fmt.Sprintf("internal_user_id = $%d", paramCount))
   462→		} else {
   463→			whereConditions = append(whereConditions, "internal_user_id = ?")
   464→		}
   465→		args = append(args, userID)
   466→	}
   467→
   468→	if search != "" {
   469→		paramCount++
   470→		searchPattern := "%" + search + "%"
   471→		if db.Driver == "pgx" || db.Driver == "duckdb" {
   472→			whereConditions = append(whereConditions, fmt.Sprintf(
   473→				"(track_id ILIKE $%d OR filename ILIKE $%d OR COALESCE(user_id, '') ILIKE $%d OR COALESCE(username, '') ILIKE $%d OR COALESCE(source, '') ILIKE $%d OR COALESCE(source_id, '') ILIKE $%d OR CAST(id AS TEXT) ILIKE $%d OR TO_CHAR(recording_date, 'YYYY-MM-DD HH24:MI:SS') ILIKE $%d)",
   474→				paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount))
   475→			args = append(args, searchPattern)
   476→		} else {
   477→			whereConditions = append(whereConditions,
   478→				"(track_id LIKE ? OR filename LIKE ? OR COALESCE(user_id, '') LIKE ? OR COALESCE(username, '') LIKE ? OR COALESCE(source, '') LIKE ? OR COALESCE(source_id, '') LIKE ? OR CAST(id AS TEXT) LIKE ? OR strftime('%Y-%m-%d %H:%M:%S', recording_date, 'unixepoch') LIKE ?)")
   479→			for i := 0; i < 8; i++ {
   480→				args = append(args, searchPattern)
   481→			}
   482→		}
   483→	}
   484→
   485→	// Build query
   486→	query = "SELECT COUNT(*) FROM uploads"
   487→	if len(whereConditions) > 0 {
   488→		query += " WHERE " + whereConditions[0]
   489→		for i := 1; i < len(whereConditions); i++ {
   490→			query += " AND " + whereConditions[i]
   491→		}
   492→	}
   493→
   494→	var count int
   495→	err := db.DB.QueryRowContext(ctx, query, args...).Scan(&count)
   496→	if err != nil {
   497→		return 0, fmt.Errorf("count uploads: %w", err)
   498→	}
   499→
   500→	return count, nil
   501→}
