				"(track_id ILIKE $%d OR filename ILIKE $%d OR COALESCE(user_id, '') ILIKE $%d OR COALESCE(username, '') ILIKE $%d OR COALESCE(source, '') ILIKE $%d OR COALESCE(source_id, '') ILIKE $%d OR COALESCE(detector, '') ILIKE $%d OR CAST(id AS TEXT) ILIKE $%d OR TO_CHAR(recording_date, 'YYYY-MM-DD HH24:MI:SS') ILIKE $%d)",
				paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount, paramCount))
			args = append(args, searchPattern)
		} else {
			whereConditions = append(whereConditions,
				"(track_id LIKE ? OR filename LIKE ? OR COALESCE(user_id, '') LIKE ? OR COALESCE(username, '') LIKE ? OR COALESCE(source, '') LIKE ? OR COALESCE(source_id, '') LIKE ? OR COALESCE(detector, '') LIKE ? OR CAST(id AS TEXT) LIKE ? OR strftime('%Y-%m-%d %H:%M:%S', recording_date, 'unixepoch') LIKE ?)")
